// Core domain types for JanSeva AI. All records in this prototype are sample data.

export type CategoryId =
  | 'roads'
  | 'parking'
  | 'garbage'
  | 'water'
  | 'streetlights'
  | 'health'
  | 'education'
  | 'other';

export type ComplaintStatus =
  | 'Submitted'
  | 'Acknowledged'
  | 'In Progress'
  | 'Action Reported'
  | 'Resolved'
  | 'Reopened'
  | 'Overdue';

/**
 * Where a piece of status information came from.
 * - official: read from an official portal (in this prototype: sample official records)
 * - user: reported by the citizen themselves
 * - demo: generated by the prototype's simulated demo path
 */
export type StatusSource = 'official' | 'user' | 'demo';

export type CitizenVerification = 'not-requested' | 'pending' | 'confirmed' | 'disputed';

export interface Category {
  id: CategoryId;
  label: string;
  labelHi: string;
  /** Category-level service timeline in days, used to compute "overdue". Illustrative values. */
  slaDays: number;
}

export interface Locality {
  id: string;
  name: string;
  ward: string;
  pin: string;
  city: string;
  state: string;
  zone: string;
  aliases: string[];
  landmarks: string[];
}

export interface Department {
  id: string;
  name: string;
  shortName: string;
  parent: string;
  categories: CategoryId[];
}

export type IntegrationLevel = 'direct-planned' | 'prepare' | 'link';
export type UrlStatus = 'public' | 'mock';

export interface ServiceEntry {
  id: string;
  name: string;
  department: string;
  directoryCategory: ServiceCategory;
  complaintCategories: CategoryId[];
  jurisdiction: string;
  purpose: string;
  requirements: string[];
  submissionMethod: string;
  url: string;
  urlStatus: UrlStatus;
  integration: IntegrationLevel;
  lastVerified: string; // ISO date
  verificationNote: string;
}

export type ServiceCategory =
  | 'Municipal services'
  | 'Roads and transport'
  | 'Parking and traffic'
  | 'Healthcare'
  | 'Education'
  | 'Water and sanitation'
  | 'Electricity and utilities'
  | 'General public grievances';

export interface AuthorityRecord {
  id: string;
  office: string;
  departmentId: string;
  jurisdiction: string;
  localityIds: string[];
  role: string;
  officerName: string; // always fictional in this prototype
  email: string;
  phone: string;
  website: string;
  websiteStatus: UrlStatus;
  grievanceChannelId: string; // ServiceEntry id
  source: string;
  verifiedOn: string; // ISO date
  isSample: true;
}

export type TimelineStage =
  | 'prepared'
  | 'submitted'
  | 'acknowledged'
  | 'assigned'
  | 'action'
  | 'resolved'
  | 'verification'
  | 'followup'
  | 'disputed'
  | 'reopened'
  | 'overdue';

export interface TimelineEvent {
  id: string;
  stage: TimelineStage;
  date: string; // ISO date-time
  note: string;
  source: StatusSource;
  /** Added by the citizen in this session; can be removed to undo. */
  removable?: boolean;
  /** Status before this event was applied, so it can be reverted. */
  prevStatus?: ComplaintStatus;
  prevVerification?: CitizenVerification;
}

export interface Complaint {
  id: string;
  ref: string;
  title: string;
  category: CategoryId;
  description: string;
  complaintText: string;
  state: string;
  city: string;
  localityId: string;
  ward: string;
  pin: string;
  landmark: string;
  coordinates?: string;
  incidentDate: string;
  departmentId: string;
  serviceId: string;
  submittedOn: string;
  lastUpdate: string;
  status: ComplaintStatus;
  statusSource: StatusSource;
  citizenVerification: CitizenVerification;
  hasPhoto: boolean;
  timeline: TimelineEvent[];
  /** Created through the simulated demo path; not submitted anywhere. */
  isDemo: boolean;
}

/** Anonymised aggregate record used by the public dashboard. No complainant data. */
export interface PublicRecord {
  id: string;
  incidentId: string;
  localityId: string;
  category: CategoryId;
  departmentId: string;
  landmark: string;
  received: string; // ISO date
  status: ComplaintStatus;
  /** null when status is Resolved but the resolution date was not recorded. */
  resolvedOn: string | null;
  feedback: 'confirmed' | 'disputed' | 'none';
}

export interface ComplaintDraft {
  title: string;
  category: CategoryId | '';
  description: string;
  complaintText: string;
  state: string;
  city: string;
  localityId: string;
  ward: string;
  pin: string;
  landmark: string;
  coordinates: string;
  incidentDate: string;
  departmentId: string;
  serviceId: string;
  photoName: string;
  photoUrl: string;
}
